def beautify_sheet(ws, widths):
    header_fill = PatternFill("solid", fgColor="1F4E78")
    header_font = Font(color="FFFFFF", bold=True)
    for cell in ws[1]:
        cell.fill = header_fill
        cell.font = header_font
        cell.alignment = Alignment(horizontal="center", vertical="center")

    for row in ws.iter_rows(min_row=2):
        for cell in row:
            cell.alignment = Alignment(wrap_text=True, vertical="top")

    for idx, width in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(idx)].width = width

    ws.freeze_panes = "A2"


def main():
    wb = Workbook()
    ws = wb.active
    ws.title = "测试用例"
    ws.append(TESTCASE_HEADERS)
    for item in testcases:
        ws.append(item)
    beautify_sheet(ws, [12, 18, 10, 34, 28, 52, 26, 52, 18])

    smoke_ws = wb.create_sheet("冒烟测试用例")
    smoke_ws.append(SMOKE_HEADERS)
    for item in smoke_cases:
        smoke_ws.append(item)
    beautify_sheet(smoke_ws, [12, 16, 28, 48])

    output_path = "prd_for_testcase/手游APP加速引擎测试用例.xlsx"
    wb.save(output_path)
    print(output_path)


if __name__ == "__main__":
    main()